<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowDown, ArrowUp, Plus, Save, Trash2 } from '@lucide/vue'
import { api, readableError } from '../../api/client'
import AsyncState from '../../components/AsyncState.vue'
import type { Problem, ProblemPayload, Tag, TestCase } from '../../types'
import { validateProblem } from '../../utils/problem-validation'

const route=useRoute();const router=useRouter();const editing=computed(()=>typeof route.params.id==='string');const state=ref<'loading'|'error'|'ready'>('ready');const tagsState=ref<'loading'|'error'|'ready'>('loading');const tagError=ref('');const error=ref('');const errors=ref<Record<string,string>>({});const saving=ref(false);const tags=ref<Tag[]>([]);const newTag=ref('');const creatingTag=ref(false)
const form=reactive<ProblemPayload>({title:'',statement:'',input:'',output:'',difficulty:'easy',time_limit_ms:1000,published:false,tags:[],test_cases:[{input:'',output:'',is_sample:true}]})
async function loadTags(){tagsState.value='loading';tagError.value='';try{tags.value=(await api.get<Tag[]>('/admin/tags')).data;tagsState.value='ready'}catch(cause){tagsState.value='error';tagError.value=readableError(cause,'标签加载失败')}}
async function load(){if(!editing.value)return;state.value='loading';try{const item=(await api.get<Problem>(`/admin/problems/${route.params.id}`)).data;Object.assign(form,{title:item.title,statement:item.statement,input:item.input,output:item.output,difficulty:item.difficulty,time_limit_ms:item.time_limit_ms,published:item.published,tags:item.tags,test_cases:(item.test_cases??[]).map(({input,output,is_sample})=>({input,output,is_sample}))});state.value='ready'}catch(cause){error.value=readableError(cause,'题目加载失败');state.value='error'}}
function addCase(){if(form.test_cases.length<50)form.test_cases.push({input:'',output:'',is_sample:false})}function removeCase(index:number){if(window.confirm(`确定删除第 ${index+1} 个测试点吗？`))form.test_cases.splice(index,1)}function move(index:number,direction:-1|1){const target=index+direction;if(target<0||target>=form.test_cases.length)return;const [item]=form.test_cases.splice(index,1);form.test_cases.splice(target,0,item as TestCase)}
async function createTag(){const name=newTag.value.trim().toLowerCase();if(!name||tagsState.value!=='ready')return;creatingTag.value=true;error.value='';try{const created=(await api.post<Tag>('/admin/tags',{name})).data;tags.value=[...tags.value.filter(tag=>tag.id!==created.id),created].sort((left,right)=>left.name.localeCompare(right.name));if(!form.tags.includes(created.name))form.tags.push(created.name);newTag.value=''}catch(cause){error.value=readableError(cause,'标签创建失败')}finally{creatingTag.value=false}}
async function save(){if(tagsState.value!=='ready'){tagError.value=tagsState.value==='loading'?'标签尚未加载完成，请稍后再试':'标签加载失败，请重新加载后再保存';return}form.tags=form.tags.filter(name=>tags.value.some(tag=>tag.name===name));errors.value=validateProblem(form);if(Object.keys(errors.value).length){document.querySelector<HTMLElement>('[aria-invalid="true"]')?.focus();return}saving.value=true;error.value='';try{if(editing.value)await api.put(`/admin/problems/${route.params.id}`,form);else await api.post('/admin/problems',form);await router.push('/admin/problems')}catch(cause){error.value=readableError(cause,'题目保存失败')}finally{saving.value=false}}
onMounted(()=>{void loadTags();void load()})
</script>
<template><AsyncState v-if="state!=='ready'" :status="state" :message="state==='loading'?'正在加载题目…':error" :on-retry="load"/><div v-else><div class="page-heading"><div><p class="eyebrow">{{editing?'修改题目':'新建题目'}}</p><h1 tabindex="-1">{{editing?'编辑题目':'创建一道新题'}}</h1><p>测试点按当前顺序评测，每个输入和输出最大 256 KiB。</p></div></div><form class="editor-form" @submit.prevent="save"><section class="card form-grid"><h2 class="full">基本信息</h2><label class="full" for="problem-title">题目名称</label><input id="problem-title" v-model="form.title" class="full" maxlength="200" :aria-invalid="!!errors.title" required/><small v-if="errors.title" class="field-error full">{{errors.title}}</small><label for="difficulty">难度</label><label for="time-limit">时间限制（毫秒）</label><select id="difficulty" v-model="form.difficulty"><option value="easy">简单 · 1 星</option><option value="medium">中等 · 2 星</option><option value="hard">困难 · 3 星</option></select><input id="time-limit" v-model.number="form.time_limit_ms" type="number" min="100" max="5000" step="100" :aria-invalid="!!errors.time_limit_ms"/><small v-if="errors.time_limit_ms" class="field-error full">{{errors.time_limit_ms}}</small><fieldset class="full"><legend>标签</legend><p v-if="tagsState==='loading'" role="status" aria-live="polite">正在加载可选标签…</p><p v-if="tagsState==='loading'&&tagError" class="feedback error" role="alert">{{tagError}}</p><p v-else-if="tagsState==='error'" class="feedback error" role="alert">{{tagError}} <button class="button button-secondary" type="button" @click="loadTags">重新加载标签</button></p><div v-else-if="tagsState==='ready'" class="tag-options"><label v-for="tag in tags" :key="tag.id" class="checkbox-row"><input v-model="form.tags" type="checkbox" :value="tag.name"/>{{tag.name}}</label></div><div class="tag-create"><label for="new-tag">新标签</label><input id="new-tag" v-model="newTag" maxlength="64"/><button class="button button-secondary" type="button" :disabled="creatingTag||tagsState!=='ready'||!newTag.trim()" @click="createTag"><Plus :size="18"/>创建标签</button></div></fieldset><label class="checkbox-row full"><input v-model="form.published" type="checkbox"/>保存后立即发布</label></section><section class="card form-stack"><h2>Markdown 内容</h2><label for="statement">题目描述</label><textarea id="statement" v-model="form.statement" rows="10" :aria-invalid="!!errors.statement" required/><small v-if="errors.statement" class="field-error">{{errors.statement}}</small><label for="input-markdown">输入说明</label><textarea id="input-markdown" v-model="form.input" rows="5"/><label for="output-markdown">输出说明</label><textarea id="output-markdown" v-model="form.output" rows="5"/></section><section class="card full"><div class="section-heading"><div><p class="eyebrow">有序评测数据</p><h2>测试点（{{form.test_cases.length}} / 50）</h2></div><button class="button button-secondary" type="button" :disabled="form.test_cases.length>=50" @click="addCase"><Plus :size="18"/>添加测试点</button></div><p v-if="errors.test_cases" class="form-error" role="alert">{{errors.test_cases}}</p><div class="case-list"><fieldset v-for="(testCase,index) in form.test_cases" :key="index" class="test-case"><legend>测试点 {{index+1}}</legend><div class="case-toolbar"><label class="checkbox-row"><input v-model="testCase.is_sample" type="checkbox"/>公开为样例</label><button class="icon-button" type="button" :disabled="index===0" :aria-label="`上移测试点 ${index+1}`" @click="move(index,-1)"><ArrowUp :size="18"/></button><button class="icon-button" type="button" :disabled="index===form.test_cases.length-1" :aria-label="`下移测试点 ${index+1}`" @click="move(index,1)"><ArrowDown :size="18"/></button><button class="icon-button danger" type="button" :aria-label="`删除测试点 ${index+1}`" @click="removeCase(index)"><Trash2 :size="18"/></button></div><label :for="`case-in-${index}`">输入</label><textarea :id="`case-in-${index}`" v-model="testCase.input" rows="5"/><label :for="`case-out-${index}`">期望输出</label><textarea :id="`case-out-${index}`" v-model="testCase.output" rows="5"/></fieldset><AsyncState v-if="!form.test_cases.length" status="empty" message="至少添加一个测试点再保存。"/></div></section><p v-if="error" class="feedback error full" role="alert">{{error}}</p><div class="form-actions full"><RouterLink class="button button-ghost" to="/admin/problems">取消</RouterLink><button class="button button-primary" type="submit" :disabled="saving"><Save :size="19"/>{{saving?'正在保存…':'保存题目'}}</button></div></form></div></template>
